// Robin keeps hidden goodwill points: insult subtracts 2, apology/gift add 1; warm if points are at least 1.
function visible(actions) {
  let points = 0;
  for (const action of actions) {
    if (action === "insult") points -= 2;
    else if (action === "apologise") points += 1;
    else if (action === "gift") points += 1;
  }
  return { mood: points >= 1 ? "warm" : "cold" };
}

// Robin compares totals: warm only when apologies outnumber insults; gifts have no effect.
function visible(actions) {
  let apologies = 0;
  let insults = 0;
  for (const action of actions) {
    if (action === "apologise") apologies++;
    else if (action === "insult") insults++;
  }
  return { mood: apologies > insults ? "warm" : "cold" };
}

// Robin uses first impression plus a grudge rule: warm iff first action is apologise and no insult directly follows another.
function visible(actions) {
  const firstIsApology = actions[0] === "apologise";
  let doubleInsult = false;
  for (let i = 1; i < actions.length; i++) {
    if (actions[i] === "insult" && actions[i - 1] === "insult") {
      doubleInsult = true;
    }
  }
  return { mood: firstIsApology && !doubleInsult ? "warm" : "cold" };
}

// Robin tracks an apology, a permanent grudge from two insults in a row, and rejects ending on an insult.
function visible(actions) {
  let hasApology = false;
  let doubleInsult = false;
  let last = null;
  for (const action of actions) {
    if (action === "apologise") hasApology = true;
    if (action === "insult" && last === "insult") doubleInsult = true;
    last = action;
  }
  return { mood: hasApology && !doubleInsult && last !== "insult" ? "warm" : "cold" };
}

