function visible(actions) {
  const filtered = actions.filter(a => a !== "gift");
  let doubleInsult = false;
  let lastInsult = -1;
  let lastApology = -1;

  for (let i = 0; i < filtered.length; i++) {
    const action = filtered[i];
    if (action === "insult" && i > 0 && filtered[i - 1] === "insult") {
      doubleInsult = true;
    }
    if (action === "insult") lastInsult = i;
    if (action === "apologise") lastApology = i;
  }

  const apologyAfterLastInsult = lastInsult === -1 || lastApology > lastInsult;
  return { mood: !doubleInsult && apologyAfterLastInsult ? "warm" : "cold" };
}

// Warm as in Rival 1, except a double insult is forgiven when at least three gifts follow the last insult and an apology comes after it.
function visible(actions) {
  let doubleInsult = false;
  let lastInsult = -1;
  let lastApology = -1;

  for (let i = 0; i < actions.length; i++) {
    const action = actions[i];
    if (action === "insult" && i > 0 && actions[i - 1] === "insult") {
      doubleInsult = true;
    }
    if (action === "insult") lastInsult = i;
    if (action === "apologise") lastApology = i;
  }

  let giftsAfterLastInsult = 0;
  if (lastInsult !== -1) {
    for (let i = lastInsult + 1; i < actions.length; i++) {
      if (actions[i] === "gift") giftsAfterLastInsult++;
    }
  }

  const apologyAfterLastInsult = lastInsult === -1 || lastApology > lastInsult;
  const normalWarm = !doubleInsult && apologyAfterLastInsult;
  const healedDouble = doubleInsult && apologyAfterLastInsult && giftsAfterLastInsult >= 3;

  return { mood: normalWarm || healedDouble ? "warm" : "cold" };
}

